\node[left] at (-0.6,2.625) {$B$};
\draw[fill=white] (7,1.6) rectangle (10,2.05);
\draw[dashed] (10,1.825) -- (11,1.825);
\draw (11,1.625) -- (11,2.025);
\node[left] at (-0.6,1.825) {$C$};
